    /// <summary>
    /// Creates a channel's line series and point buffer and registers both with the plot.
    /// </summary>
    /// <remarks>
    /// The caller must hold <c>PlotModel.SyncRoot</c> and raises the <c>PlotModel</c> change
    /// notification after releasing it. Since issue #595 the only caller is the drain, on the UI
    /// thread; the lock is what keeps OxyPlot's own update and render, which take the same lock, from
    /// seeing a half-updated series list.
    /// </remarks>
    // @port: Daqifi.Desktop.Logger.PlotLogger.AddChannelSeries
    private void AddChannelSeries(string channelName, string DeviceSerialNo, ChannelType channelType, string newColor)
    {
        var key = (DeviceSerialNo, channelName);
        var newDataPoints = new List<DataPoint>();

        var serialSuffix = DeviceSerials.ToShortDisplay(DeviceSerialNo);

        var newLineSeries = new LineSeries
        {
            Title = channelName,
            ItemsSource = newDataPoints,
            Color = ChannelSeriesColor.ParseOrFallback(newColor),
            // Collapse the points that land on one pixel column to that column's first, min, max and
            // last before drawing, so the geometry drawn is at most about four points per pixel of
            // width and a spike narrower than a pixel still shows. Every buffered point is still
            // transformed and grouped, so that part scales with the buffer. The tracker reads the
            // undecimated points, so hover values are unchanged.
            Decimator = OxyPlot.Decimator.Decimate,
            TrackerFormatString = $"{channelName} ({serialSuffix})\n{{1}}: {{2}}\n{{3}}: {{4:0.######}}"
        };

        // Synchronize IsVisible with the IChannel
        if (LoggingManager.Instance != null)
        {
            var subscribedChannel = LoggingManager.Instance.SubscribedChannels
                .FirstOrDefault(ch => ch.DeviceSerialNo == DeviceSerialNo && ch.RecordedName == channelName);

            if (subscribedChannel != null)
            {
                newLineSeries.IsVisible = subscribedChannel.IsVisible;
            }
            // Optional: else, default to true or log a warning if channel not found
            // For now, if not found, it will use the default LineSeries.IsVisible (which is true)
        }

        newLineSeries.YAxisKey = channelType switch
        {
            ChannelType.Analog => "Analog",
            ChannelType.Digital => "Digital",
            _ => newLineSeries.YAxisKey
        };

        // Structural Adds to the shared collections, under PlotModel.SyncRoot, which the caller (the
        // drain) holds. The caller raises the PlotModel change notification after releasing the lock.
        LoggedPoints.Add(key, newDataPoints);
        LoggedChannels.Add(key, newLineSeries);
        // Indexer, not Add. The key cannot be present today — LoggedChannels.Add above would have
        // thrown first — but this is bookkeeping, and it should not be the thing that takes the
        // transport thread down if the two ever fall out of step.
        _rawSeriesColors[key] = newColor;
        PlotModel.Series.Add(newLineSeries);
    }

    private bool _firstRenderTickLogged;

    // @port: Daqifi.Desktop.Logger.PlotLogger.CompositionTargetRendering
    private void CompositionTargetRendering(object? sender, EventArgs e)
    {
        if (!_firstRenderTickLogged)
        {
            // QA breadcrumb (2026-07-13 live-graph triage): discriminates "render tick
            // never fires" from "tick fires but the PlotView doesn't repaint".
            _firstRenderTickLogged = true;
            Common.Loggers.AppLogger.Instance.Information("Plot render tick active (first tick fired).");
        }

        var now = _stopwatch.ElapsedMilliseconds;
        if (_lastTickRedrew && _lastTickMs >= 0)
        {
            _lastRedrawCostMs = RedrawCostMs(now - _lastTickMs, _lastTickWorkMs);
        }

        _lastTickMs = now;
        _lastTickRedrew = false;
        if (!IsRedrawDue(now, _lastUpdateMilliSeconds, _lastRedrawCostMs))
        {
            return;
        }

        var tickStart = Stopwatch.GetTimestamp();

        int drained;
        bool addedSeries;
        lock (PlotModel.SyncRoot)
        {
            // Move what the transport thread queued since the last redraw into the series. Here, on
            // the UI thread and on the redraw's own cadence, so the transport thread never waits for
            // this lock (issue #595).
            drained = DrainPendingSamplesLocked(out addedSeries);

            // Mirror each subscribed channel's visibility onto its series. A change here needs a redraw
            // even when no new sample has arrived, e.g. a channel hidden while the device is idle.
            var visibilityChanged = false;
            if (LoggingManager.Instance != null) // Ensure LoggingManager instance is available
            {
                foreach (var channel in LoggingManager.Instance.SubscribedChannels)
                {
                    // The series is keyed by the name the samples carry, which is not the channel's
                    // current name after a rename during the session (#668).
                    var key = (channel.DeviceSerialNo, channel.RecordedName);
                    if (LoggedChannels.TryGetValue(key, out LineSeries series))
                    {
                        if (series.IsVisible != channel.IsVisible)
                        {
                            series.IsVisible = channel.IsVisible;
                            visibilityChanged = true;
                        }
                    }
                }
            }

            if (_hasNewData || visibilityChanged)
            {
                _hasNewData = false;
                PlotModel.InvalidatePlot(true);
                _lastTickRedrew = true;
            }

            if (IsStatsDue(now, _lastStatsMilliSeconds))
            {
                UpdatePlotStatsSummary();
                if (_lastStatsMilliSeconds % 60000 < 1000 && LoggedPoints.Count > 0)
                {
                    // QA breadcrumb: once a minute while channels exist, record what the
                    // plot layer believes it holds — points reaching here but not the
                    // screen indicts the view/invalidation side.
                    Common.Loggers.AppLogger.Instance.Information(
                        $"Plot tick: {PlotModel.Series.Count} series, " +
                        $"{LoggedPoints.Values.Sum(pl => pl.Count)} buffered points; stats: {PlotStatsSummary}");
                }
                _lastStatsMilliSeconds = now;
            }

            _lastUpdateMilliSeconds = now;
        }

        _lastTickWorkMs = Stopwatch.GetElapsedTime(tickStart).TotalMilliseconds;

        // Raised outside the lock, like every other change notification here.
        RaiseAfterDrain(drained, addedSeries);
    }

    /// <summary>
    /// Recomputes <see cref="PlotStatsSummary"/> from the currently buffered points. Called from the
    /// render tick every <see cref="STATS_INTERVAL_MS"/> while holding <c>PlotModel.SyncRoot</c>.
    /// Every mutation of the per-channel collections — the drain's point-append and
    /// <see cref="AddChannelSeries"/>'s series creation — takes that same lock, so enumerating the
    /// point lists here is consistent (no torn reads, no structural-modification race).
    /// Gap markers are inserted as <c>DataPoint.Undefined</c> (NaN X); a real sample always has a
    /// finite X (elapsed ms), so an NaN X distinguishes a gap from data and lets a genuinely
    /// non-finite sample VALUE still be counted (nonfinite) rather than hidden.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.PlotLogger.UpdatePlotStatsSummary
    private void UpdatePlotStatsSummary()
    {
        PlotStatsSummary = BuildPlotStatsSummary(PlotModel.Series.Count, LoggedPoints.Values);
    }

    /// <summary>
    /// Builds the <see cref="PlotStatsSummary"/> string from a series count and the per-series
    /// point lists. Pure and side-effect-free so it can be unit-tested without a live PlotModel.
    /// Gap markers (<c>DataPoint.Undefined</c>, i.e. NaN X) are excluded from the point count and
    /// never mistaken for a non-finite sample value; <c>nonfinite</c> counts only real samples
    /// (finite X) whose VALUE (Y) is NaN/Inf; <c>last</c> is the value at the greatest X seen.
    /// <c>firstx</c>/<c>lastx</c> are the smallest/greatest axis X (elapsed ms) across finite-valued
    /// samples — the harness's window onto the time-axis anchor (issue #573).
    /// </summary>
    internal static string BuildPlotStatsSummary(int seriesCount, IEnumerable<List<DataPoint>> pointLists)
    {
        long points = 0;
        long nonFinite = 0;
        var min = double.NaN;
        var max = double.NaN;
        var last = double.NaN;
        var firstX = double.NaN;
        var lastX = double.NegativeInfinity;

        foreach (var pointList in pointLists)
        {
            for (var i = 0; i < pointList.Count; i++)
            {
                var point = pointList[i];
                if (double.IsNaN(point.X))
                {
                    // Gap marker (DataPoint.Undefined), not data.
                    continue;
                }

                points++;

                var y = point.Y;
                if (double.IsNaN(y) || double.IsInfinity(y))
                {
                    nonFinite++;
                    continue;
                }

                // y is finite here (the non-finite values were counted and skipped above), so the
                // NaN test is only ever true before the first value lands — the same
                // nothing-seen-yet sentinel firstX uses on the next line.
                if (double.IsNaN(min) || y < min)
                {
                    min = y;
                }

                if (double.IsNaN(max) || y > max)
                {
                    max = y;
                }

                if (double.IsNaN(firstX) || point.X < firstX)
                {
                    firstX = point.X;
                }

                if (point.X >= lastX)
                {
                    lastX = point.X;
                    last = y;
                }
            }
        }

        return string.Format(
            CultureInfo.InvariantCulture,
            "series={0};points={1};nonfinite={2};last={3:R};min={4:R};max={5:R};firstx={6:R};lastx={7:R}",
            seriesCount, points, nonFinite, last, min, max,
            firstX, double.IsNegativeInfinity(lastX) ? double.NaN : lastX);
    }

    // @port: Daqifi.Desktop.Logger.PlotLogger.ClearPlot
    public void ClearPlot()
    {
        // The structural clears take PlotModel.SyncRoot, the lock the drain, AddChannelSeries, the
        // render tick and OxyPlot's own update and render hold, so a clear can never interleave with
        // them and tear the collections (issue #759). Samples still queued from before the clear are
        // discarded with it: they belong to the acquisition being cleared.
        lock (PlotModel.SyncRoot)
        {
            while (_pendingSamples.TryDequeue(out _))
            {
                Interlocked.Decrement(ref _pendingCount);
            }

            Volatile.Write(ref _pendingOverflowed, 0);
            LoggedChannels.Clear();
            LoggedPoints.Clear();
            _rawSeriesColors.Clear();
            PlotModel.Series.Clear();
            PlotModel.InvalidatePlot(true);
            FirstTime = null;
        }

        // Raised outside the lock, like every other change notification here: no binding handler may
        // run while the plot lock is held.
        PlotStatsSummary = EMPTY_PLOT_STATS_SUMMARY;
        HasPlotData = false;
        OnPropertyChanged(nameof(LoggedChannels));
        OnPropertyChanged(nameof(LoggedPoints));
        OnPropertyChanged(nameof(PlotModel));
    }

